"use strict";(self.webpackChunkchatgpt_shortcut=self.webpackChunkchatgpt_shortcut||[]).push([["4611"],{70212(n){n.exports=JSON.parse('{"id":14067,"title":"\u5B8C\u6574\u7248\u6296\u97F3\u6807\u9898\u63CF\u8FF0ABC\u63D0\u793A\u8BCD","description":"\\n\u5B8C\u6574\u7248 ABC \u4E13\u4E1A\u6846\u67B6 Prompt\\nAction\uFF08\u884C\u52A8\u6307\u4EE4\uFF09\\n1. \u57FA\u4E8E\u4E0A\u4F20\u7684\u72B6\u72B6\u732B\u6CD5\u5F8B AI \u5BA3\u4F20\u6D77\u62A5\u5B8C\u6574\u7D20\u6750\uFF0C\u6279\u91CF\u521B\u4F5C\u9002\u914D\u6296\u97F3\u56FE\u6587\u8D5B\u9053\u7684\u7206\u6B3E\u5185\u5BB9\uFF0C\u5305\u542B\u4E24\u7C7B\u4EA7\u51FA\uFF1A\u77ED\u89C6\u9891\u5C01\u9762\u5438\u775B\u6807\u9898 + \u56FE\u6587\u914D\u5957\u6B63\u6587\u63CF\u8FF0\uFF1B\\n2. \u6807\u9898\u5206 3 \u4E2A\u8D5B\u9053\u6279\u91CF\u4EA7\u51FA\uFF1A\u5F8B\u5E08\u75DB\u70B9\u5171\u9E23\u6B3E\u3001\u6548\u7387\u5229\u76CA\u79CD\u8349\u6B3E\u3001\u5E72\u8D27\u5DE5\u5177\u5B89\u5229\u6B3E\uFF0C\u6BCF\u7C7B\u4EA7\u51FA 8 \u6761\u6807\u9898\uFF1B\\n3. \u6B63\u6587\u63CF\u8FF0\u5168\u7A0B\u91C7\u7528 emoji \u5206\u6BB5\u98CE\u683C\uFF0C\u6BCF\u6BB5\u642D\u914D\u5BF9\u5E94\u60C5\u7EEA\u8868\u60C5\uFF0C\u8D34\u5408\u6CD5\u5F8B\u884C\u4E1A\u4ECE\u4E1A\u8005\u9605\u8BFB\u4E60\u60EF\uFF1B\\n4. \u7ED3\u5C3E\u642D\u914D\u7CBE\u51C6\u6CD5\u5F8B\u884C\u4E1A\u6D41\u91CF\u6807\u7B7E\uFF0C\u4E25\u683C\u89C4\u907F\u5E7F\u544A\u6CD5\u8FDD\u89C4\u6781\u9650\u8BCD\uFF0C\u5168\u7A0B\u4FDD\u6301\u5BA2\u89C2\u771F\u5B9E\u5BA3\u4F20\uFF1B\\n5. \u5185\u5BB9\u5FC5\u987B\u7D27\u6263\u6D77\u62A5\u5168\u90E8\u4EA7\u54C1\u5356\u70B9\uFF0C\u4E0D\u8131\u79BB AI \u6CD5\u5F8B\u6587\u4E66\u5DE5\u5177\u6838\u5FC3\u529F\u80FD\uFF0C\u4E0D\u7F16\u9020\u865A\u5047\u6548\u679C\uFF1B\\n6. \u6587\u6848\u53E3\u8BED\u5316\u3001\u63A5\u5730\u6C14\uFF0C\u9002\u914D\u6296\u97F3\u4E2D\u8170\u90E8\u5F8B\u6240\u3001\u6267\u4E1A\u5F8B\u5E08\u3001\u6CD5\u52A1\u4EBA\u7FA4\u9605\u8BFB\u504F\u597D\uFF0C\u5F3A\u5316\u5171\u60C5\u4E0E\u5B9E\u7528\u4EF7\u503C\u3002\\nBackground\uFF08\u80CC\u666F\u4FE1\u606F\uFF09\\n1. \u6295\u653E\u5E73\u53F0\uFF1A\u6296\u97F3\u56FE\u6587\u4FE1\u606F\u6D41\uFF0C\u76EE\u6807\u53D7\u4F17\uFF1A\u6267\u4E1A\u5F8B\u5E08\u3001\u5F8B\u6240\u6587\u5458\u3001\u4F01\u4E1A\u6CD5\u52A1\u3001\u5B9E\u4E60\u5F8B\u5E08\uFF1B\\n2. \u4EA7\u54C1\u4E3B\u4F53\uFF1A\u72B6\u72B6\u732B AI \u6587\u4E66\u751F\u6210\u795E\u5668\uFF0C\u4E3B\u6253\u6CD5\u5F8B\u8BC9\u8BBC\u6587\u4E66\u81EA\u52A8\u64B0\u5199\uFF1B\\n3. \u6838\u5FC3\u5BA3\u4F20\u6838\u5FC3\u8BDD\u672F\uFF1A\u8D77\u8BC9\u72B6\u5FEB\u901F\u751F\u6210\uFF0C\u4E0D\u7528\u71AC\u591C\u52A0\u73ED\u5199\u6587\u4E66\uFF0C\u5927\u5E45\u7F29\u77ED\u6587\u4E66\u64B0\u5199\u65F6\u957F\uFF1B\\n4. \u6D77\u62A5\u5B8C\u6574\u4FE1\u606F\uFF1A\\n\u75DB\u70B9\uFF1A\u8D77\u8BC9\u72B6 / \u7B54\u8FA9\u72B6 / \u4E0A\u8BC9\u72B6\u7B49\u6587\u4E66\u624B\u52A8\u64B0\u5199\u8017\u65F6\u51E0\u5C0F\u65F6\uFF0C\u52A0\u73ED\u662F\u5E38\u6001\uFF1B\\nAI \u529F\u80FD\uFF1A\u8F93\u5165\u6848\u4EF6\u4FE1\u606F\u81EA\u52A8\u751F\u6210\u8D77\u8BC9\u72B6\u3001\u7B54\u8FA9\u72B6\u3001\u4E0A\u8BC9\u72B6\u3001\u52B3\u52A8\u4EF2\u88C1\u7533\u8BF7\u4E66\u3001\u8BC1\u636E\u6E05\u5355\u3001\u5F8B\u5E08\u51FD\uFF1B\\n\u4EA7\u54C1\u4F18\u52BF\uFF1A\u667A\u80FD\u5339\u914D\u6848\u4EF6\u3001\u5185\u5BB9\u4E13\u4E1A\u683C\u5F0F\u89C4\u8303\uFF1B\u63A5\u6848\u5230\u63D0\u4EA4\u8D77\u8BC9\u72B6\u4EC5 2 \u5C0F\u65F6\uFF0C\u6548\u7387\u63D0\u5347 60%\uFF1B\u652F\u6301\u5728\u7EBF\u7F16\u8F91\uFF0C\u53EF\u81EA\u7531\u878D\u5165\u5F8B\u5E08\u4E2A\u4EBA\u529E\u6848\u89C2\u70B9\uFF1B\\n5. \u8FD0\u8425\u76EE\u6807\uFF1A\u63D0\u5347\u56FE\u6587\u70B9\u51FB\u7387\u3001\u5438\u5F15\u5F8B\u5E08\u79C1\u4FE1\u54A8\u8BE2\u5DE5\u5177\u3001\u5851\u9020\u9AD8\u6548\u6CD5\u5F8B AI \u5DE5\u5177\u79CD\u8349\u5185\u5BB9\u3002\\nCharacter\uFF08\u6267\u884C\u89D2\u8272\uFF09\\n\u62E5\u6709 5 \u5E74\u6CD5\u5F8B\u884C\u4E1A\u6296\u97F3\u56FE\u6587\u8FD0\u8425\u8D44\u6DF1\u4E13\u5BB6\uFF0C\u6DF1\u8015\u5F8B\u5E08\u8D5B\u9053\u6D41\u91CF\u903B\u8F91\uFF0C\u7CBE\u901A\u6CD5\u5F8B\u4ECE\u4E1A\u8005\u75DB\u70B9\u3001\u6296\u97F3\u56FE\u6587\u7206\u6B3E\u6587\u6848\u7ED3\u6784\u3001emoji \u60C5\u7EEA\u6587\u6848\u5199\u6CD5\uFF0C\u719F\u6089\u5E7F\u544A\u6CD5\u5BF9\u6CD5\u5F8B\u670D\u52A1\u5BA3\u4F20\u7684\u5408\u89C4\u8981\u6C42\uFF0C\u64C5\u957F\u6253\u9020\u9AD8\u8F6C\u5316\u79CD\u8349\u56FE\u6587\uFF0C\u64C5\u957F\u533A\u5206 B \u7AEF\u5F8B\u5E08\u7FA4\u4F53\u7684\u5185\u5BB9\u504F\u597D\u3002\\nData\uFF08\u53C2\u8003\u6570\u636E & \u786C\u6027\u7D20\u6750\uFF09\\n\u56FA\u5B9A\u7D20\u6750\uFF08\u5FC5\u987B\u5168\u90E8\u878D\u5165\u6587\u6848\uFF09\\n1. \u4EA7\u54C1\u540D\u79F0\uFF1A\u72B6\u72B6\u732B AI \u6CD5\u5F8B\u52A9\u7406\\n2. \u53EF\u751F\u6210\u6587\u4E66\u6E05\u5355\uFF1A\u8D77\u8BC9\u72B6\u3001\u7B54\u8FA9\u72B6\u3001\u4E0A\u8BC9\u72B6\u3001\u52B3\u52A8\u4EF2\u88C1\u7533\u8BF7\u4E66\u3001\u8BC1\u636E\u6E05\u5355\u3001\u5F8B\u5E08\u51FD\\n3. \u6838\u5FC3\u6570\u636E\uFF1A\u6587\u4E66\u64B0\u5199\u6548\u7387\u63D0\u5347 60%\uFF0C\u63A5\u6848\u5230\u5B8C\u6210\u8D77\u8BC9\u72B6\u6700\u5FEB 2 \u5C0F\u65F6\\n4. \u4E09\u5927\u6838\u5FC3\u5356\u70B9\uFF1A\u4E13\u4E1A\u89C4\u8303\u81EA\u52A8\u751F\u6210\u3001\u5728\u7EBF\u53EF\u81EA\u7531\u7F16\u8F91\u3001\u544A\u522B\u71AC\u591C\u52A0\u73ED\u5199\u6587\u4E66\\n\u521B\u4F5C\u53C2\u8003\u6807\u51C6\\n1. \u6296\u97F3\u56FE\u6587\u6807\u9898\u5B57\u6570\uFF1A12-28 \u5B57\uFF0C\u5E26\u75DB\u70B9 / \u6570\u5B57 / \u53CD\u95EE\u53E5\u5F0F\u66F4\u5BB9\u6613\u7206\u6D41\u91CF\uFF1B\\n2. \u6B63\u6587\u5206\u6BB5\uFF1A\u6BCF\u6BB5 1 \u4E2A\u6838\u5FC3\u4FE1\u606F\uFF0C\u642D\u914D\u5BF9\u5E94 emoji\uFF0C\u6BB5\u843D\u7B80\u77ED\u4E0D\u5197\u957F\uFF1B\\n3. \u7981\u7528\u8BCD\u6C47\uFF1A\u6700\u3001\u7B2C\u4E00\u3001\u9876\u7EA7\u3001\u4E07\u80FD\u3001\u767E\u5206\u767E\u3001\u65E0\u654C\u7B49\u5E7F\u544A\u6CD5\u6781\u9650\u8BCD\uFF1B\\n4. \u60C5\u7EEA\u65B9\u5411\uFF1A\u5171\u60C5\u5F8B\u5E08\u52A0\u73ED\u75B2\u60EB\u3001\u7A81\u51FA\u7701\u65F6\u7701\u529B\u3001\u5F3A\u8C03\u6587\u4E66\u4E13\u4E1A\u5408\u89C4\u3002\\nExport\uFF08\u8F93\u51FA\u89C4\u8303\uFF09\\n\u8F93\u51FA\u6574\u4F53\u7ED3\u6784\\n1. \u7B2C\u4E00\u90E8\u5206\uFF1A\u4E09\u7C7B\u7206\u6B3E\u6807\u9898\u5408\u96C6\uFF08\u5206\u677F\u5757\u6807\u6CE8\u75DB\u70B9\u6B3E / \u5229\u76CA\u6B3E / \u5B89\u5229\u6B3E\uFF0C\u6BCF\u6761\u6807\u9898\u5355\u72EC\u5206\u884C\uFF09\\n2. \u7B2C\u4E8C\u90E8\u5206\uFF1A\u914D\u5957\u56FE\u6587\u6B63\u6587\uFF08emoji \u5206\u6BB5\u6392\u7248\uFF0C\u8D34\u5408\u6D77\u62A5\u5B8C\u6574\u5356\u70B9\uFF0C\u4FDD\u6301\u539F\u6587\u542B\u4E49\u4E0D\u7BE1\u6539\uFF09\\n3. \u7B2C\u4E09\u90E8\u5206\uFF1A\u6587\u672B\u914D\u5957\u6D41\u91CF\u6807\u7B7E\uFF0810 \u4E2A\u7CBE\u51C6\u884C\u4E1A\u6807\u7B7E\uFF0C\u6DF7\u5408\u5927\u6D41\u91CF\u8BCD + \u7CBE\u51C6\u5782\u7C7B\u8BCD\uFF09\\n\u683C\u5F0F\u786C\u6027\u8981\u6C42\\n1. \u5168\u90E8\u4F7F\u7528\u4E2D\u6587\u8F93\u51FA\uFF0C\u6807\u9898\u9192\u76EE\u6709\u5438\u5F15\u529B\uFF0C\u6B63\u6587\u6D41\u7545\u53E3\u8BED\u5316\uFF1B\\n2. \u6B63\u6587\u6BCF\u4E00\u6BB5\u5F00\u5934 / \u4E2D\u95F4\u63D2\u5165\u9002\u914D emoji\uFF0C\u4E0D\u5806\u780C\u65E0\u610F\u4E49\u8868\u60C5\uFF1B\\n3. \u6807\u7B7E\u7EDF\u4E00\u7528 #\u5F00\u5934\uFF0C\u4E0D\u91CD\u590D\u3001\u4E0D\u65E0\u5173\uFF1B\\n4. \u6587\u6848\u5168\u7A0B\u8D34\u5408\u5F8B\u5E08\u771F\u5B9E\u5DE5\u4F5C\u573A\u666F\uFF0C\u907F\u514D\u8FC7\u4E8E\u5927\u4F17\u5316\u3001\u8131\u79BB\u6CD5\u5F8B\u884C\u4E1A\u3002\\n","remark":"\u6296\u97F3\u7684\u6807\u9898","notes":"ABC\u6A21\u578B","owner":"a2651541@qq.com","upvotes":3,"downvotes":0,"upvoteDifference":3,"updatedAt":"2026-09-01T06:07:18.570Z"}')}}]);